FUNCTION_BLOCK FB_ValueComparison
VAR_INPUT
    input1 : DINT := 0;
    input2 : DINT := 0;
    input3 : DINT := 0;
    input4 : DINT := 0;
    input5 : DINT := 0;
    CYCLE  : DINT := 0;
END_VAR
VAR_OUTPUT
    M : DINT;
    N : DINT;
    UPDATED_CYCLE : DINT;
END_VAR
VAR
    TEMP_MAX_OUT   : DINT;
    TEMP_MIN_2_OUT : DINT;
    TEMP_MIN_3_OUT : DINT;
    INSTANCE_MAX   : USER_MAX;
    INSTANCE_MIN   : USER_MIN;
    tempCalc       : DINT;
END_VAR
BEGIN
    // Step 1: Calculate the intermediate maximum value (TEMP_MAX_OUT)
    INSTANCE_MAX(in1 := input2, in2 := input3);
    TEMP_MAX_OUT := INSTANCE_MAX.OUT;

    // Step 2: Calculate M as the maximum value between input1 and TEMP_MAX_OUT
    INSTANCE_MAX(in1 := input1, in2 := TEMP_MAX_OUT);
    M := INSTANCE_MAX.OUT;

    // Step 3: Calculate the intermediate minimum value (TEMP_MIN_2_OUT)
    INSTANCE_MIN(in1 := input4, in2 := input5);
    TEMP_MIN_2_OUT := INSTANCE_MIN.OUT;

    // Step 4: Calculate another intermediate value (TEMP_MIN_3_OUT)
    tempCalc := input3 * TEMP_MIN_2_OUT + input2;
    INSTANCE_MIN(in1 := input2, in2 := tempCalc);
    TEMP_MIN_3_OUT := INSTANCE_MIN.OUT;

    // Step 5: Calculate N as the minimum value between input1 and the sum of TEMP_MIN_3_OUT + input3
    tempCalc := TEMP_MIN_3_OUT + input3;
    INSTANCE_MIN(in1 := input1, in2 := tempCalc);
    N := INSTANCE_MIN.OUT;

    // Update the cycle counter
    UPDATED_CYCLE := CYCLE + 1;
END_FUNCTION_BLOCK
